--
-- Structure de la table `consigne_groupe_champ`
--

DROP TABLE IF EXISTS `consigne_groupe_champ`;
CREATE TABLE IF NOT EXISTS `consigne_groupe_champ` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `consigne_groupe_id` bigint UNSIGNED NOT NULL,
  `champ_id` bigint UNSIGNED NOT NULL,
  `ordre` int NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `consigne_groupe_champ_consigne_groupe_id_foreign` (`consigne_groupe_id`),
  KEY `consigne_groupe_champ_champ_id_foreign` (`champ_id`)
) ENGINE=MyISAM AUTO_INCREMENT=3156 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

