--
-- Structure de la table `datamaps`
--

DROP TABLE IF EXISTS `datamaps`;
CREATE TABLE IF NOT EXISTS `datamaps` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `position` int NOT NULL,
  `longueur` int NOT NULL,
  `codification_id` bigint UNSIGNED NOT NULL,
  `champ_id` bigint UNSIGNED NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `datamap_codification_id_foreign` (`codification_id`),
  KEY `datamap_champ_id_foreign` (`champ_id`)
) ENGINE=MyISAM AUTO_INCREMENT=1208 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

